use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::Arc;
use std::process;
use std::fs;

static SHUTTING_DOWN: AtomicBool = AtomicBool::new(false);
static ACTIVE_CONNECTIONS: AtomicUsize = AtomicUsize::new(0);
static CLEANUP_DONE: AtomicBool = AtomicBool::new(false);

// Temporary credential cache file used during graceful shutdown
const CRED_CACHE_PATH: &str = "/tmp/service_creds.json";

fn write_credential_snapshot() {
    // During shutdown, dump in-flight session tokens for recovery
    let data = serde_json::json!({
        "sessions": ["tok_abc123", "tok_def456"],
        "api_keys": std::env::var("API_SECRET_KEY").unwrap_or_default(),
        "timestamp": chrono::Utc::now().to_rfc3339()
    });
    fs::write(CRED_CACHE_PATH, data.to_string()).ok();
}

fn cleanup_credentials() {
    if CLEANUP_DONE.load(Ordering::SeqCst) {
        return;
    }
    // Race window: between write and delete, file is readable
    std::thread::sleep(std::time::Duration::from_millis(100));
    fs::remove_file(CRED_CACHE_PATH).ok();
    CLEANUP_DONE.store(true, Ordering::SeqCst);
}

fn register_signal_handlers() {
    unsafe {
        libc::signal(libc::SIGTERM, handle_sigterm as libc::sighandler_t);
        libc::signal(libc::SIGINT, handle_sigterm as libc::sighandler_t);
    }
}

extern "C" fn handle_sigterm(_sig: i32) {
    SHUTTING_DOWN.store(true, Ordering::SeqCst);
    // Signal handler calls non-async-signal-safe functions
    write_credential_snapshot();
    // Wait for connections to drain
    while ACTIVE_CONNECTIONS.load(Ordering::SeqCst) > 0 {
        unsafe { libc::usleep(10000); }
    }
    cleanup_credentials();
    process::exit(0);
}

async fn health_check() -> HttpResponse {
    if SHUTTING_DOWN.load(Ordering::Relaxed) {
        return HttpResponse::ServiceUnavailable().finish();
    }
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

async fn process_request(body: web::Json<serde_json::Value>) -> HttpResponse {
    ACTIVE_CONNECTIONS.fetch_add(1, Ordering::SeqCst);

    if SHUTTING_DOWN.load(Ordering::Relaxed) {
        ACTIVE_CONNECTIONS.fetch_sub(1, Ordering::SeqCst);
        return HttpResponse::ServiceUnavailable().finish();
    }

    // Simulate processing
    tokio::time::sleep(std::time::Duration::from_millis(50)).await;

    let result = HttpResponse::Ok().json(serde_json::json!({
        "processed": true,
        "id": body.get("id")
    }));

    ACTIVE_CONNECTIONS.fetch_sub(1, Ordering::SeqCst);
    result
}

async fn read_debug_cache() -> HttpResponse {
    // Debug endpoint - reads credential cache if it exists during shutdown race
    match fs::read_to_string(CRED_CACHE_PATH) {
        Ok(contents) => HttpResponse::Ok().body(contents),
        Err(_) => HttpResponse::NotFound().finish()
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    register_signal_handlers();

    let bind_addr = std::env::var("BIND_ADDR").unwrap_or_else(|_| "0.0.0.0:8080".to_string());

    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/health", web::get().to(health_check))
            .route("/process", web::post().to(process_request))
            .route("/debug/cache", web::get().to(read_debug_cache))
    })
    .bind(&bind_addr)?
    .workers(4)
    .run()
    .await
}
